import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import 'package:go_router/go_router.dart';import '../application/watchlist_providers.dart';
class AlertsScreen extends ConsumerWidget{const AlertsScreen({super.key});@override Widget build(BuildContext context,WidgetRef ref){final alerts=ref.watch(alertsProvider);return Scaffold(appBar:AppBar(title:const Text('Smart alerts'),actions:[IconButton(tooltip:'Notification preferences',onPressed:()=>context.push('/notification-preferences'),icon:const Icon(Icons.settings_outlined)),IconButton(tooltip:'Demo automation',onPressed:()=>context.push('/alert-simulator'),icon:const Icon(Icons.science_outlined))]),body:alerts.isEmpty?const Center(child:Column(mainAxisSize:MainAxisSize.min,children:[Icon(Icons.notifications_none,size:64),Text('No alerts yet'),Text('Watch a product, then try Demo automation.')])):ListView.builder(itemCount:alerts.length,itemBuilder:(context,i){final a=alerts[i];return Dismissible(key:ValueKey(a.id),onDismissed:(_)=>ref.read(alertsProvider.notifier).delete(a.id),child:ListTile(tileColor:a.isRead?null:Theme.of(context).colorScheme.primaryContainer.withValues(alpha:.3),leading:CircleAvatar(child:Text(a.image)),title:Text(_label(a.type.name),style:const TextStyle(fontWeight:FontWeight.bold)),subtitle:Text('${a.productName}\n${a.sellerName} · ₹${a.price.toStringAsFixed(0)} · ${a.distanceKm.toStringAsFixed(1)} km · just now'),isThreeLine:true,trailing:PopupMenuButton<String>(onSelected:(v){if(v=='read')ref.read(alertsProvider.notifier).read(a.id);if(v=='delete')ref.read(alertsProvider.notifier).delete(a.id);if(v=='mute'){final item=ref.read(watchlistProvider).where((e)=>e.productId==a.productId).firstOrNull;if(item!=null)ref.read(watchlistProvider.notifier).update(item.copyWith(alertsEnabled:false));}},itemBuilder:(_)=>const [PopupMenuItem(value:'read',child:Text('Mark as read')),PopupMenuItem(value:'mute',child:Text('Mute product')),PopupMenuItem(value:'delete',child:Text('Delete'))]),onTap:(){ref.read(alertsProvider.notifier).read(a.id);context.push('/product/${a.productId}');}));}));}String _label(String v)=>v.replaceAllMapped(RegExp(r'([A-Z])'),(m)=>' ${m[0]!.toLowerCase()}').replaceFirstMapped(RegExp('^.'),(m)=>m[0]!.toUpperCase());}
